import {themeFor} from './themes.mjs';
import {drawCityLife} from './effects.mjs';
import {WORLD,BUILDINGS,LANDMARKS,SHARDS,actors,echoAt} from './engine.mjs';
export const iso=(x,y,z=0)=>({x:594+(x-y)*32,y:96+(x+y)*16-z});
export const uniso=(x,y)=>({x:((x-594)/32+(y-96)/16)/2,y:((y-96)/16-(x-594)/32)/2});
export function createRenderer(canvas){const c=canvas.getContext('2d');let t=0,theme=themeFor('afterglow');const previousPositions=new Map();const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const poly=(pts,fill,stroke)=>{c.beginPath();pts.forEach((p,i)=>i?c.lineTo(p.x,p.y):c.moveTo(p.x,p.y));c.closePath();if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=1;c.stroke();}};
 const tile=(x,y,w,h,fill,z=0)=>poly([iso(x,y,z),iso(x+w,y,z),iso(x+w,y+h,z),iso(x,y+h,z)],fill);
 const line=(a,b,color,width=1)=>{c.beginPath();c.moveTo(a.x,a.y);c.lineTo(b.x,b.y);c.strokeStyle=color;c.lineWidth=width;c.stroke();};
 const circle=(x,y,r,color)=>{c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fillStyle=color;c.fill();};
 const text=(str,x,y,color,size=10,align='center',font='sans-serif')=>{c.font=`${size}px ${font}`;c.textAlign=align;c.fillStyle=color;c.fillText(str,x,y);};
 const box=(x,y,w,h,z,color,side='#3c5358',front='#526667')=>{poly([iso(x,y+h),iso(x+w,y+h),iso(x+w,y+h,z),iso(x,y+h,z)],front);poly([iso(x+w,y),iso(x+w,y+h),iso(x+w,y+h,z),iso(x+w,y,z)],side);tile(x,y,w,h,color,z);};
 const glow=(p,r,color)=>{const g=c.createRadialGradient(p.x,p.y,0,p.x,p.y,r);g.addColorStop(0,color);g.addColorStop(1,'transparent');circle(p.x,p.y,r,g);};
 function tree(x,y,type=0){const p=iso(x,y);c.save();c.translate(p.x,p.y);c.scale(1,.5);circle(4,3,20,'#071c2955');c.restore();line(p,{x:p.x,y:p.y-34},'#7d7961',4);const colors=type?theme.bloom:theme.tree;circle(p.x,p.y-42,20,colors[0]);circle(p.x-10,p.y-37,13,colors[1]);circle(p.x+8,p.y-49,14,colors[2]);circle(p.x+14,p.y-33,13,colors[0]);}
 function building(b){const {x,y,w,h,z,name}=b,color=theme.building[BUILDINGS.indexOf(b)%theme.building.length];const shadow=[iso(x,y+h),iso(x+w,y+h),iso(x+w+.6,y+h+.6),iso(x+.6,y+h+.6)];poly(shadow,'#081e2944');box(x,y,w,h,z,color,'#4b5273','#646486');box(x-.08,y-.08,w+.16,h+.16,8,'#9ba68d','#4f635d','#697d6d');tile(x-.08,y-.08,w+.16,h+.16,color,z+3);line(iso(x,y,z+5),iso(x+w,y,z+5),'#ffffff28',2);for(let i=.4;i<w-.1;i+=.65){const p=iso(x+i,y+h,z-23);poly([{x:p.x-6,y:p.y},{x:p.x+7,y:p.y+6},{x:p.x+7,y:p.y+21},{x:p.x-6,y:p.y+15}],'#e9dca0');glow({x:p.x,y:p.y+10},22,'#e9dca01c');if(z>80){const q=iso(x+i,y+h,z-54);poly([{x:q.x-6,y:q.y},{x:q.x+7,y:q.y+6},{x:q.x+7,y:q.y+21},{x:q.x-6,y:q.y+15}],'#b9d0b6');}}for(let i=.3;i<h-.1;i+=.7){const p=iso(x+w,y+i,z-24);poly([{x:p.x-6,y:p.y+3},{x:p.x+7,y:p.y-3},{x:p.x+7,y:p.y+12},{x:p.x-6,y:p.y+18}],'#91b5b4');}const door=iso(x+w*.45,y+h);poly([{x:door.x-8,y:door.y-23},{x:door.x+7,y:door.y-16},{x:door.x+7,y:door.y},{x:door.x-8,y:door.y-7}],'#2f4b50');const sign=iso(x+w*.55,y+h,z*.6);c.save();c.translate(sign.x,sign.y);c.transform(1,.5,0,1,0,0);c.fillStyle='#263e43';c.fillRect(-38,-7,76,15);text(name,0,4,'#e1dfbb',7);c.restore();box(x+.3,y+.25,.6,.5,z+12,'#7e9185','#627c73','#71877c');}
 function lamp(x,y){const p=iso(x,y);line(p,{x:p.x,y:p.y-36},'#93aaa0',2);line({x:p.x,y:p.y-36},{x:p.x+10,y:p.y-36},'#93aaa0',2);circle(p.x+10,p.y-35,3,'#ede5a8');glow({x:p.x+10,y:p.y-31},32,'#e6d7a426');tile(x-.2,y-.2,.5,.5,'#e9d9ab18');}
 function pad(p,color,active,label){const v=iso(p.x,p.y);glow(v,active?60:38,active?color+'55':color+'1c');tile(p.x-.6,p.y-.6,1.2,1.2,'#243d44');tile(p.x-.48,p.y-.48,.96,.96,active?color:color+'66');poly([iso(p.x-.6,p.y-.6),iso(p.x+.6,p.y-.6),iso(p.x+.6,p.y+.6),iso(p.x-.6,p.y+.6)],null,color);if(active){c.save();c.globalAlpha=.25;poly([iso(p.x-.6,p.y-.6,26),iso(p.x+.6,p.y-.6,26),iso(p.x+.6,p.y+.6,26),iso(p.x-.6,p.y+.6,26)],color);c.restore();}text(active?'✓':label,v.x,v.y+3,'#edf0d1',11);}
 function actor(a,ghost=false,highlight=false){const p=iso(a.x,a.y),previous=previousPositions.get(a.id),moving=previous&&Math.hypot(a.x-previous.x,a.y-previous.y)>.001;previousPositions.set(a.id,{x:a.x,y:a.y});const stride=moving?Math.sin(t*13)*4:0;const bob=reduce?0:Math.sin(t*(moving?13:3)+a.x)*(moving?1.8:.65);c.save();if(ghost)c.globalAlpha=.56;glow(p,ghost?31:20,ghost?'#8ae0d833':'#dce99a22');c.save();c.translate(p.x,p.y+2);c.scale(1,.45);circle(0,0,ghost?10:8,'#071c2966');c.restore();const col=ghost?'#9cddd6':a.color||'#dce99a';if(ghost){const recent=a.frames?.filter(f=>f.t<=a.time&&f.t>a.time-3)||[];if(recent.length>1){c.beginPath();for(let i=0;i<recent.length;i++){const q=iso(recent[i].x,recent[i].y);i?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y);}c.strokeStyle='#9ce0dc55';c.lineWidth=2;c.stroke();}}line({x:p.x-3,y:p.y-5+bob},{x:p.x-3+stride,y:p.y-1},'#243b47',3);line({x:p.x+3,y:p.y-5+bob},{x:p.x+3-stride,y:p.y-1},'#243b47',3);c.fillStyle=col;c.beginPath();c.roundRect(p.x-7,p.y-20+bob,14,15,5);c.fill();circle(p.x,p.y-25+bob,6,'#d6b99a');circle(p.x-1,p.y-28+bob,6,ghost?'#a4d8d1':'#344d50');c.fillStyle='#d6b99a';c.fillRect(p.x-5,p.y-25+bob,10,6);if(ghost){c.strokeStyle='#a5eee2';c.lineWidth=1;c.strokeRect(p.x-8,p.y-21+bob,16,17);}if(highlight){c.save();c.strokeStyle=theme.accent+'99';c.lineWidth=1.5;c.setLineDash([3,5]);c.beginPath();c.ellipse(p.x,p.y+1,15,7,0,0,Math.PI*2);c.stroke();c.restore();}if(highlight||ghost){const label=ghost?'ECHO '+a.loop:a.name||'YOU';const w=label.length*5+15;c.fillStyle=ghost?'#183d46d9':'#142c35e8';c.beginPath();c.roundRect(p.x-w/2,p.y-49+bob,w,14,4);c.fill();text(label.toUpperCase(),p.x,p.y-39+bob,ghost?'#9ce0dc':'#dce99a',7);}c.restore();}
 function tram(g){const departure=g.time>85?Math.min(10,(g.time-85)*2):0;const x=12.2+departure,y=4;box(x,y,3,1.1,31,g.power?'#e9af8b':'#b39380','#a17060','#c29478');tile(x+.15,y+.12,2.7,.86,'#ead4b0',34);for(let i=.35;i<2.9;i+=.55){const p=iso(x+i,y+1.11,24);poly([{x:p.x-5,y:p.y},{x:p.x+6,y:p.y+5},{x:p.x+6,y:p.y+14},{x:p.x-5,y:p.y+9}],g.power?'#e7e8a6':'#36545b');}const q=iso(x+3,y+.5,16);glow(q,45,g.power?'#ede4ac44':'transparent');circle(q.x,q.y,3,g.power?'#ffefb5':'#718c8d');const top=iso(x+1.5,y+.5,45);text('LAST TRAM',top.x,top.y,'#e6d9b7',7);if(g.power&&g.time<85){const d=iso(13.6,5.3);glow(d,30,'#dce99a3a');text('↓ BOARD HERE',d.x,d.y+18,'#dce99a',8);}}
 return function draw(g,wallTime,myId='solo',route=[],camera=null,visuals={}){theme=themeFor(visuals.theme);t=reduce||visuals.motion===false?0:wallTime;c.clearRect(0,0,1200,760);const bg=c.createRadialGradient(600,320,30,600,380,700);bg.addColorStop(0,theme.sky[0]);bg.addColorStop(1,theme.sky[1]);c.fillStyle=bg;c.fillRect(0,0,1200,760);c.save();if(camera){c.translate(600,380);c.scale(camera.zoomX||camera.zoom,camera.zoomY||camera.zoom);c.translate(-camera.x,-camera.y);}
 // Floating district foundation, laid as individually shaded isometric paving tiles.
 poly([iso(0,WORLD.h),iso(WORLD.w,WORLD.h),iso(WORLD.w,WORLD.h,-20),iso(0,WORLD.h,-20)],'#284552');poly([iso(WORLD.w,0),iso(WORLD.w,WORLD.h),iso(WORLD.w,WORLD.h,-20),iso(WORLD.w,0,-20)],'#213b49');
 for(let y=0;y<WORLD.h;y++)for(let x=0;x<WORLD.w;x++){const noise=((x*17+y*31)%11)/110;const road=(x>=2&&x<=4)||(y>=5&&y<=7)||(y>=10&&y<=11)||(y>=16&&y<=17)||(x>=19&&x<=20);const palette=road?theme.road:theme.ground;tile(x,y,1,1,palette[(x*3+y*5)%3]);poly([iso(x,y),iso(x+1,y),iso(x+1,y+1),iso(x,y+1)],null,`rgba(14,46,53,${.08+noise})`);}
 // Canal, moving reflections, bridge, and the gate the echoes can hold.
 tile(7.5,0,1,WORLD.h,theme.water);for(let i=0;i<50;i++){const y=(i*.43+(reduce?0:t*.09))%WORLD.h;const p=iso(7.7,y);line(p,{x:p.x+13,y:p.y+6},i%3?'#559ba643':'#8fc7bd44',1);}tile(7.35,7.1,1.3,1.8,'#9a9c83');for(let y=7.2;y<8.9;y+=.2)line(iso(7.35,y),iso(8.65,y),'#c1b89533');for(let y=.1;y<WORLD.h;y+=.35){if(y>7&&y<9)continue;line(iso(7.45,y),iso(7.45,y,11),'#90a799',2);line(iso(8.55,y),iso(8.55,y,11),'#789b98',2);}for(const x of [7.45,8.55]){line(iso(x,0,10),iso(x,7,10),'#9bb3a3',1.5);line(iso(x,9,10),iso(x,WORLD.h,10),'#9bb3a3',1.5);}if(!g.gateOpen){line(iso(8,7.1,20),iso(8,8.9,20),'#e2b37d',4);for(let y=7.1;y<9;y+=.25)line(iso(8,y),iso(8,y,20),'#af9977',2);}else{line(iso(7.45,7.1),iso(7.45,7.1,30),'#dcdfa0',3);glow(iso(8,8),45,'#dce99a22');}
 // Track, flowers, scattered road markings and illuminated station platform.
 for(const y of [3.7,4.7])line(iso(9,y),iso(WORLD.w,y),'#182f3d',3);for(let x=9;x<WORLD.w;x+=.45)line(iso(x,3.55),iso(x,4.9),'#82918a',2);tile(12,5,4.6,.65,'#b7b397');for(let x=12.1;x<16.5;x+=.3)tile(x,5,.08,.3,'#e9d99e');for(let i=0;i<7;i++)tile(2.4+i*.15,10,.07,.6,'#b8c3a333');
 pad(WORLD.gatePad,'#e8ba82',g.gateOpen,'I');pad(WORLD.powerPad,'#93d6d6',g.power,'II');const gp=iso(5,9),pp=iso(12,10);text('GATE',gp.x,gp.y+30,'#e3c59b',8);text('POWER',pp.x,pp.y+30,'#a0d4d3',8);
 const drawables=BUILDINGS.map(b=>({depth:b.x+b.y+b.w+b.h,fn:()=>building(b)}));
 const trees=[[.8,4.8,1],[5.8,5,0],[.9,12.1,0],[6.2,12.6,1],[10,6.3,0],[15.7,6.9,1],[15,12.6,0],[11,7.4,0],[6.3,7.1,1]];trees.forEach(([x,y,a])=>drawables.push({depth:x+y,fn:()=>tree(x,y,a)}));[[4.8,5],[6,10.7],[10.1,5.8],[14,6.1],[12.8,11.5]].forEach(([x,y])=>drawables.push({depth:x+y,fn:()=>lamp(x,y)}));
 drawables.push({depth:9.5,fn:()=>{const p=iso(3,6);box(2.75,5.8,.5,.45,25,g.ticket?'#83aaa0':'#e1bd83','#75958b','#aeb894');glow({x:p.x,y:p.y-20},g.ticket?25:50,g.ticket?'#9ce0dc22':'#efda9255');circle(p.x,p.y-34+(reduce?0:Math.sin(t*2)*3),3,g.ticket?'#a4ccc0':'#f1df9f');text(g.ticket?'TICKET FOUND':'TICKET KIOSK',p.x,p.y-49,'#e9dda5',8);}});
 drawables.push({depth:17,fn:()=>tram(g)});g.echoes.forEach(e=>{const a=echoAt(e,g.time);if(a)drawables.push({depth:a.x+a.y,fn:()=>actor({...a,time:g.time},true)});});g.players.forEach(p=>drawables.push({depth:p.x+p.y,fn:()=>actor(p,false,p.id===myId)}));for(const l of LANDMARKS){drawables.push({depth:l.x+l.y,fn:()=>{const q=iso(l.x,l.y);glow(q,45,'#dce99a33');circle(q.x,q.y-25,4,'#dce99a');line(q,{x:q.x,y:q.y-22},'#dce99a77',1);text(l.name.toUpperCase(),q.x,q.y-39,'#dce99a',8);}});}drawables.push({depth:26,fn:()=>drawCityLife(c,iso,t,theme,{reduced:reduce||visuals.motion===false,shards:SHARDS,collected:g.shards||[]})});for(const [x,y,a] of [[19,6,1],[21,6.4,0],[20,8.5,1],[22,13,0],[20,16.6,1],[23,16,0],[5,17,1],[5,18.5,0],[17,14,0],[18,18,1]])drawables.push({depth:x+y,fn:()=>tree(x,y,a)});drawables.sort((a,b)=>a.depth-b.depth).forEach(d=>d.fn());
 // World details and wayfinding are drawn into the scene, not external images.
 const label=(x,y,str)=>{const p=iso(x,y);c.save();c.translate(p.x,p.y);c.transform(1,.5,-1,.5,0,0);text(str,0,0,'#d0d8b94d',13);c.restore();};label(4,12.5,'YESTERDAY LANE');label(11,6.7,'TOMORROW STATION');label(20,9,'LANTERN GARDEN');label(19,17.5,'THE LONG WAY HOME');
 if(g.started&&g.time<1.3){const q=iso(WORLD.spawn.x,WORLD.spawn.y),r=15+g.time*65;c.save();c.globalAlpha=Math.max(0,1-g.time/1.3);c.strokeStyle=theme.accent;c.lineWidth=2;c.beginPath();c.ellipse(q.x,q.y,r,r*.5,0,0,Math.PI*2);c.stroke();c.restore();}if(route.length){c.save();c.setLineDash([3,7]);c.strokeStyle='#dce99a60';c.lineWidth=2;c.beginPath();route.forEach((v,i)=>{const q=iso(v.x,v.y);i?c.lineTo(q.x,q.y):c.moveTo(q.x,q.y);});c.stroke();c.restore();const end=iso(route.at(-1).x,route.at(-1).y);c.strokeStyle='#dce99a';c.beginPath();c.ellipse(end.x,end.y,8,4,0,0,Math.PI*2);c.stroke();}
 if(!reduce&&visuals.motion!==false&&visuals.weather!==false){c.save();c.strokeStyle='#c4d6dc14';c.lineWidth=.8;for(let i=0;i<100;i++){const x=(i*137.31+t*29)%1200,y=(i*93.23+t*155)%760;line({x,y},{x:x-4,y:y+11},'#b8d9d41c',.7);}for(let i=0;i<12;i++){const x=210+(i*97%800),y=130+(i*53%430)+Math.sin(t*.8+i)*8;circle(x,y,1.2,'#dce99a44');}c.restore();}
 c.restore();const vig=c.createRadialGradient(600,360,180,600,360,680);vig.addColorStop(0,'#10212b00');vig.addColorStop(1,'#10212b99');c.fillStyle=vig;c.fillRect(0,0,1200,760);
 };}
